window.products.push({"id":602953,"name":"Mr. Beer Let it Bee Honey Blond Ale Recipe","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61Cm+zWTgFL._AC_SL1500_.jpg","description":"This golden straw colored beauty is a very seasonable beer with floral honey notes, and some sweetness to round out the subtle hop character. While this beer may be light in body, it's big on flavor. This recipe includes 1 Can Canadian Blonde Brewing Extract, 1 Packet Dry Brewing Yeast (under lid of Brewing Extract), 1 Packet Honey Malt (4 oz. You'll only use 2 oz. for this recipe), 1 Packet Pilsen Malt (4 oz. You'll only use 2 oz. for this recipe), 1 Packet Mt. Hood Hop Pellets (0.5 oz.), 2 Muslin Sacks and 1 Packet No-Rinse Cleanser.","images":["https://m.media-amazon.com/images/I/61Cm+zWTgFL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Mr. Beer","source_asin":"B01DFTYYOA","category_path":"Home & Kitchen"},"sku":"BM-602953","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01DFTYYOA","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01DFTYYOA","price_pending":true,"merchant_ready":false});
